package test;
import org.eclipse.jface.text.source.Annotation;

public class TestClass {
    public int compareAnnotations(Annotation a, Annotation b) {
        // Original code potentially throwing NPE if a.getText() or b.getText() is null
        return a.getText().compareTo(b.getText());
    }

    // Example with nulls to demonstrate NPE
    public int compareAnnotationsWithNulls() {
        Annotation a = new Annotation("type", false, null);
        Annotation b = new Annotation("type", false, "some text");
        return a.getText().compareTo(b.getText()); // This would throw NPE
    }
}

afterExample:
package test;
import org.eclipse.jface.text.source.Annotation;

public class TestClass {
    public int compareAnnotations(Annotation a, Annotation b) {
        // Null-safe comparison applied by the rule
        return a.getText() == null ? (b.getText() == null ? 0 : -1) : (b.getText() == null ? 1 : a.getText().compareTo(b.getText()));
    }

    // Example with nulls, now handled gracefully
    public int compareAnnotationsWithNulls() {
        Annotation a = new Annotation("type", false, null);
        Annotation b = new Annotation("type", false, "some text");
        return a.getText() == null ? (b.getText() == null ? 0 : -1) : (b.getText() == null ? 1 : a.getText().compareTo(b.getText()));
    }
}

